import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR-0013: Initial Inference Runner and Model Selection","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/adrs/0013-initial-inference-runner-and-model-selection.md"},"headers":[],"relativePath":"sovereign-os/adrs/0013-initial-inference-runner-and-model-selection.md","filePath":"sovereign-os/adrs/0013-initial-inference-runner-and-model-selection.md"}'),r={name:"sovereign-os/adrs/0013-initial-inference-runner-and-model-selection.md"};function o(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0013-initial-inference-runner-and-model-selection" tabindex="-1">ADR-0013: Initial Inference Runner and Model Selection <a class="header-anchor" href="#adr-0013-initial-inference-runner-and-model-selection" aria-label="Permalink to &quot;ADR-0013: Initial Inference Runner and Model Selection&quot;">​</a></h1><p><strong>Status:</strong> Accepted</p><p><strong>Date:</strong> 2026-08-09</p><p><strong>Decision owner:</strong> Project creator</p><p><strong>Related RFCs/research:</strong><a href="./../rfcs/0002-local-conversation-and-inference-runtime.html">RFC-0002</a> (Accepted), <a href="./0004-provider-neutral-assistant-and-web-search.html">ADR-0004</a> (Accepted; names this ADR as required follow-up: &quot;Record the selected runner and initial model in a later ADR&quot;), <a href="./0012-local-inference-resource-and-dns-latency-budgets.html">ADR-0012</a> (Accepted), <a href="./../research/local-ai-options.html">docs/research/local-ai-options.md</a>, <a href="./../research/llamacpp-qwen2.5-3b-benchmark-report.html">llama.cpp 3B</a>, <a href="./../research/llamacpp-qwen2.5-7b-benchmark-report.html">llama.cpp 7B</a>, <a href="./../research/ollama-qwen2.5-3b-benchmark-report.html">Ollama 3B</a>, <a href="./../research/v1-corpus-benchmark-report.html">v1 corpus</a>, and <a href="./../research/dns-latency-during-generation-qualification-report.html">DNS-latency-during-generation</a> qualification reports.</p><p><strong>Supersedes:</strong> None</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Six real hardware qualification passes now exist against the qualification Raspberry Pi 5, spanning two runners (llama.cpp, Ollama), two model sizes (Qwen2.5-3B, Qwen2.5-7B), two corpora (a 5-item starter corpus that hit a ceiling effect, and a 28-item corpus built specifically to break it), and a real during-generation DNS-latency measurement. ADR-0012 turned that evidence into an accepted numeric budget policy. This ADR makes the selection decision ADR-0004 named as required follow-up, using that evidence and that policy together.</p><h3 id="the-evidence-summarized" tabindex="-1">The Evidence, Summarized <a class="header-anchor" href="#the-evidence-summarized" aria-label="Permalink to &quot;The Evidence, Summarized&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>llama.cpp + Qwen2.5-3B</th><th>llama.cpp + Qwen2.5-7B</th><th>Ollama + Qwen2.5-3B</th></tr></thead><tbody><tr><td>Starter corpus (5 items)</td><td>5/5</td><td>5/5</td><td>5/5</td></tr><tr><td>v1 corpus (28 items, 20 scored)</td><td><strong>17/20 (85%)</strong></td><td>Not run (see below)</td><td>15/20 (75%)</td></tr><tr><td>Speed (starter corpus)</td><td>4.7–5.3 tok/s</td><td>0.4–2.3 tok/s (2–10x slower)</td><td>4.5–5.2 tok/s once warm</td></tr><tr><td>First-request latency</td><td>Fast (0.18s TTFT, eager model load)</td><td>Fast (eager load)</td><td><strong>Slow (6.96s TTFT, lazy model load)</strong>, reproduced twice</td></tr><tr><td>Memory</td><td>~28% (within ADR-0012&#39;s 40% budget)</td><td>~58% (<strong>exceeds</strong> the 40% budget)</td><td>~28% once loaded</td></tr><tr><td>Peak temperature</td><td>83.2–84.2°C</td><td>84.8°C</td><td>82.6–83.7°C</td></tr><tr><td>DNS latency during generation</td><td><strong>Measured</strong>: 50ms budget held (max 41.25ms, 136 samples)</td><td>Not measured</td><td>Not measured</td></tr></tbody></table><p>The llama.cpp-7B v1-corpus run was deliberately never attempted — after the llama.cpp-3B v1-corpus pass confirmed real thermal throttling for the first time in this series, the project owner chose to skip the heaviest remaining configuration rather than push it further. That gap turns out not to matter for this decision: <strong>7B already fails ADR-0012&#39;s memory budget outright</strong> (~58% observed vs. a 40% ceiling), independent of any further accuracy or thermal data. No amount of additional 7B benchmarking changes that a model already known not to fit the accepted resource budget doesn&#39;t need more evidence to be excluded.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Runner: llama.cpp</strong>, via its official Docker server image (<code>ghcr.io/ggml-org/llama.cpp:server</code>), speaking the OpenAI-compatible chat-completions API <code>sovereign_inference.py</code>&#39;s <code>LlamaCppProvider</code> already implements against RFC-0002&#39;s Inference Provider Adapter contract.</p><p><strong>Model: Qwen2.5-3B-Instruct, Q4_K_M quantization</strong>, the specific artifact benchmarked throughout this series: <code>https://huggingface.co/Qwen/Qwen2.5-3B-Instruct-GGUF/resolve/main/qwen2.5-3b-instruct-q4_k_m.gguf</code>, SHA-256 <code>626b4a6678b86442240e33df819e00132d3ba7dddfe1cdc4fbb18e0a9615c62d</code>, 2,104,932,768 bytes.</p><h3 id="why-llama-cpp-over-ollama" tabindex="-1">Why llama.cpp Over Ollama <a class="header-anchor" href="#why-llama-cpp-over-ollama" aria-label="Permalink to &quot;Why llama.cpp Over Ollama&quot;">​</a></h3><p>Both runners tied on the trivial starter corpus (a ceiling effect the v1 corpus was built to break) and were comparably fast once an Ollama model was warm. But two real, measured differences favor llama.cpp:</p><ol><li><strong>Accuracy on the harder corpus.</strong> 85% vs. 75% on the identical 28-item v1 corpus, with Ollama showing a specific, reproducible pattern of defaulting to <code>pihole.status</code> regardless of what was actually asked. This is not attributable to a different underlying model — both ran Qwen2.5-3B at the same Q4_K_M quantization <em>level</em> — though the exact GGUF build differs (Ollama&#39;s own library vs. the Hugging Face community file), a disclosed and unresolved variable the v1-corpus report already named.</li><li><strong>No cold-start penalty.</strong> llama-server loads its one configured model eagerly, before accepting any request. Ollama loads lazily on first use — reproduced identically across two independent runs, a 6.96-second time-to-first-token on a question that took llama.cpp 0.18 seconds. For a household assistant, the first question after any period of inactivity is not a rare edge case; it is likely the <em>typical</em> case. A multi-second penalty on exactly that interaction is a real product cost llama.cpp&#39;s eager loading avoids entirely.</li></ol><p>Ollama&#39;s own stated advantages — simpler model acquisition, a convenient development workflow (<code>docs/research/local-ai-options.md</code>&#39;s original comparison table) — remain real, but are not reasons to accept worse measured accuracy and a real latency penalty in the <em>production</em> path. Ollama remains available as an optional development/evaluation tool, per ADR-0004&#39;s original framing; it is not selected as the production runner.</p><h3 id="why-qwen2-5-3b-over-qwen2-5-7b" tabindex="-1">Why Qwen2.5-3B Over Qwen2.5-7B <a class="header-anchor" href="#why-qwen2-5-3b-over-qwen2-5-7b" aria-label="Permalink to &quot;Why Qwen2.5-3B Over Qwen2.5-7B&quot;">​</a></h3><p>7B matched 3B&#39;s accuracy on every corpus it was tried against (both hit the same 5/5 ceiling on the starter corpus) — no measured benefit — at a real, substantial cost: 2–10x slower, roughly double the memory footprint, and the hottest peak temperature observed in this entire series (84.8°C, within 0.2°C of the confirmed throttle point). Per ADR-0012&#39;s accepted 40%-of-RAM budget, 7B&#39;s ~58% memory footprint disqualifies it independent of every other finding. There is no evidence-based reason to spend the resource headroom.</p><h3 id="scope-of-this-decision" tabindex="-1">Scope of This Decision <a class="header-anchor" href="#scope-of-this-decision" aria-label="Permalink to &quot;Scope of This Decision&quot;">​</a></h3><p>This selects the runner and <em>initial</em> model — not a permanent, unchangeable choice. RFC-0002&#39;s provider-neutral contract exists specifically so this can change without redesigning the Conversation Service around it. This ADR also does not claim an exhaustive model search: only Qwen2.5 at two sizes was evaluated. Other model families (Llama, Phi, Gemma, and others) were never benchmarked. Qwen2.5-3B is selected because it is the first candidate that was measured, met every accepted budget, and showed no reason to look further — not because it was proven best among all possibilities.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Unblocks the Conversation Service (RFC-0002&#39;s Delivery Sequence item 4, &quot;implement conversation streaming without capabilities&quot;) — the runner/model selection was the last thing standing between the already-built capability infrastructure (<code>sovereign_capabilities.py</code>, <code>sovereign_pihole.py</code>, <code>sovereign_system.py</code>, all hardware-qualified) and an actual product experience using it.</li><li>The deferred llama.cpp-7B v1-corpus run, named as open in every prior report in this series, is now moot: 7B is excluded on the memory budget alone, and no further benchmarking of it is needed to reach that conclusion.</li><li>Gives Sovereign Model Management (RFC-0002&#39;s separate, still- unspecified component) a concrete first artifact — digest, source, and quantization already recorded here — to build its manifest format around, rather than an abstract requirement.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>Ollama&#39;s real advantages (simpler model acquisition/management) are given up in the production path. If Sovereign Model Management later finds llama.cpp&#39;s model lifecycle genuinely harder to build than expected, this tradeoff may need revisiting.</li><li>This decision rests on Qwen2.5 exclusively. If Qwen2.5-3B&#39;s real-world conversation quality (as opposed to the narrow capability-selection accuracy this benchmark measures) proves inadequate once the Conversation Service is real, a broader model search is a real, not-yet-done piece of work this ADR doesn&#39;t preempt.</li><li>The specific GGUF build tested is a third-party community quantization (<code>Qwen/Qwen2.5-3B-Instruct-GGUF</code> on Hugging Face), not an official Qwen release artifact — a supply-chain provenance question Sovereign Model Management will need to address (digest verification exists in this ADR&#39;s evidence trail; a broader trust policy for model sources does not exist yet).</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>ADR-0012&#39;s two revisit conditions are only partially validated for this exact configuration: the DNS-latency-during-generation budget is confirmed for llama.cpp-3B on the starter corpus specifically, but the realistic intermittent-use thermal pass has not been done at all, for any configuration. If that pass later shows even intermittent use throttles this device, it affects the selected configuration exactly as much as any other — this ADR does not reduce that risk, only documents that it remains open (see Required Follow-up).</li><li>Committing to Qwen2.5-3B before a broader model search risks having to redo evaluation work if a different model family later proves meaningfully better. RFC-0002&#39;s provider-neutral contract bounds the cost of that (no architectural rework), but real benchmark and qualification effort would still need repeating.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Select Ollama for its operational convenience, accepting the cold-start penalty.</strong> Rejected: a multi-second delay on what is likely the <em>typical</em> first interaction is a real, user-visible product cost, not a rare edge case worth trading away measured accuracy for.</li><li><strong>Select Qwen2.5-7B for potential quality headroom.</strong> Rejected: no benchmark run showed any accuracy benefit over 3B, and 7B fails ADR-0012&#39;s memory budget outright — there is no real evidence to weigh against that failure.</li><li><strong>Wait for the realistic-use thermal pass and a broader model search before deciding anything.</strong> Rejected: six real qualification passes already provide clear, converging, non-contradictory evidence for this specific choice. Per this project&#39;s own precedent (ADR-0012 itself accepted provisional budgets rather than waiting for perfect data), deciding now with disclosed, non-blocking gaps unblocks real product work; waiting only delays it for marginal additional confidence in a conclusion the existing data already supports clearly.</li></ul><h2 id="required-follow-up" tabindex="-1">Required Follow-up <a class="header-anchor" href="#required-follow-up" aria-label="Permalink to &quot;Required Follow-up&quot;">​</a></h2><ul><li>The realistic, intermittent-use thermal pass ADR-0012 already named as an open revisit condition — now specifically important for the selected configuration (llama.cpp + Qwen2.5-3B), not a generic benchmark exercise.</li><li>Sovereign Model Management&#39;s model-manifest format and provenance/ trust policy (RFC-0002&#39;s still-open piece), using this ADR&#39;s recorded digest as its first real artifact.</li><li>Real conversation-quality evaluation once the Conversation Service exists — this ADR&#39;s evidence is entirely about capability-selection accuracy and resource budgets, not the opened-ended chat quality a household would actually experience.</li></ul><h2 id="validation-and-revisit-conditions" tabindex="-1">Validation and Revisit Conditions <a class="header-anchor" href="#validation-and-revisit-conditions" aria-label="Permalink to &quot;Validation and Revisit Conditions&quot;">​</a></h2><p>This ADR should be revisited if:</p><ul><li>Real Conversation Service usage reveals conversation quality problems this benchmark&#39;s narrow capability-selection metric couldn&#39;t have caught.</li><li>The realistic intermittent-use thermal pass shows the selected configuration doesn&#39;t hold within ADR-0012&#39;s budget under real household usage patterns, not just stress-test bursts.</li><li>A future model or runner candidate is evaluated against the same method and budgets and shows a clear, measured improvement — this selection is a starting point RFC-0002&#39;s provider-neutral contract makes replaceable, not a closed question.</li></ul>',36)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
